      if (bubble || pickDoctrine) return;
      var x0 = Layout.left, x1 = Layout.right, pad = 18, lines = [], title = "", acts2 = globalActions(), sub = null;
      if (mode) { title = Lang.t("Choose the target"); lines = [Lang.t(MODE_TEXT[mode])]; acts2 = [{ label: Lang.t("Cancel"), on: true, act: function () { mode = null; } }]; }
      else if (selected >= 0) {
        var r = regions[selected];
        acts2 = regionActions().concat(acts2);
        return layoutRegionCard(r, cardInfo(r), acts2);
      } else if (!acts2.length) return;
      ctx.font = font(22, false);
      var wrapped = [];
      lines.forEach(function (l) { wrapLines(l, x1 - x0 - pad * 2).forEach(function (t) { if (wrapped.length < 4) wrapped.push(t); }); });
      var rowsN = layoutChips(acts2, x0 + pad, x1 - pad, 0);
