      var x0 = Layout.left, x1 = Layout.right, W = x1 - x0, y = RC.head + 8 + RC.body + 8, tx = RC.pad + 44;
      ctx.font = font(22, false);
      I.lines.forEach(function (l) {
        l.wrapped = wrapLines(l.text, W - tx - RC.pad).slice(0, 2);
        l.y = y; l.h = Math.max(l.sign != null ? RC.sign : 0, l.wrapped.length * RC.line) + 6;
        y += l.h;
      });
      var rowsN = layoutChips(acts2, x0 + RC.pad, x1 - RC.pad, 0);
