        var SP = paperOn("send", "send", sb.x, sb.y, sb.w, sb.h, gesture && gesture.send ? { fill: "#e9dcb6" } : null);
        var cy = sb.h / 2, frac = phase === "plan" ? 1 - timer / tickLen : 0;
        if (frac > 0) {
          var late = frac < 0.15, ink = late ? BAD_COL : "#f0a400", ex = sb.w * frac, k;
          ctx.save(); ppPath(ctx, SP.outline); ctx.clip();
          ctx.globalAlpha *= late ? 0.5 + 0.12 * Math.sin(clock * 9) : 0.55;
          ctx.fillStyle = ink; ctx.beginPath(); ctx.moveTo(-10, -10);
          for (k = 0; k <= 8; k++) ctx.lineTo(ex + 5 * Math.sin(k * 1.7 + clock * 2.2), -10 + (sb.h + 20) * k / 8);
          ctx.lineTo(-10, sb.h + 10); ctx.closePath(); ctx.fill();
          // the wet rim, a shade darker, where the wash meets the dry paper
          ctx.lineWidth = 3; ctx.strokeStyle = ink; ctx.beginPath();
          for (k = 0; k <= 8; k++) ctx[k ? "lineTo" : "moveTo"](ex + 5 * Math.sin(k * 1.7 + clock * 2.2), -10 + (sb.h + 20) * k / 8);
          ctx.stroke();
          ctx.restore();
        }
        // the words then the crane, centred together on the plate
        var cr = art(scenArt("crane")), n = playerOrderList().length, sub = phase === "plan";
        var head = phase === "resolve" ? Lang.t("Marching") : Lang.t("Send orders");
        var note = !sub ? "" : n ? Lang.t(n === 1 ? "1 order drawn" : "{n} orders drawn").replace("{n}", n) : Lang.t("Waiting for orders");
        var SEAL = 30, sw = cr ? 14 + SEAL * 2 : 0, tmax = sb.w - 28 - sw;
        ctx.font = font(26, true); var tw = ctx.measureText(head).width;
        if (sub) { ctx.font = font(20, false); tw = Math.max(tw, ctx.measureText(note).width); }
        tw = Math.min(tw, tmax);
        var tx = (sb.w - tw - sw) / 2;
        ctx.textAlign = "left"; ctx.textBaseline = "middle";
        ctx.fillStyle = CAMP[BLUE].dark; ctx.font = font(26, true);
        ctx.fillText(head, tx, cy - (sub ? 11 : 0), tmax);
        if (sub) { ctx.font = font(20, false); ctx.fillStyle = INK; ctx.fillText(note, tx, cy + 17, tmax); }
        // the crane in a ring of dashed stitches: its weight sits up-left of its
