        g.fillStyle = TERRAIN[opt.terrain || "meadow"].c[1]; g.beginPath(); g.ellipse(W / 2, H / 2 + 8, W / 2 - 30, H / 2 - 30, 0, 0, Math.PI * 2); g.fill();
