          g.fillStyle = C.base; g.strokeStyle = C.dark; g.lineWidth = 2;
          var y = H - 46, dir = b > a ? 1 : -1;
          g.beginPath(); g.moveTo(a + dir * 30, y - 8); g.lineTo(b - dir * 46, y - 8); g.lineTo(b - dir * 46, y - 18);
          g.lineTo(b - dir * 22, y); g.lineTo(b - dir * 46, y + 18); g.lineTo(b - dir * 46, y + 8); g.lineTo(a + dir * 30, y + 8); g.closePath();
          g.fill(); g.stroke();
